def load() -> pd.DataFrame:
    import pandas as pd
    from pandas import ExcelFile

    paths = [
        'data/archeology/input/climateMeasurements.xlsx',
        'data/archeology/input/radiocarbon_database_regional.xlsx'
    ]
    rows = []
    for p in paths:
        xf = ExcelFile(p)
        for s in xf.sheet_names:
            rows.append({'file': p.split('/')[-1], 'sheet': s})
    return pd.DataFrame(rows)

def process(climateMeasurements) -> pd.DataFrame:
    import pandas as pd
    cols = list(climateMeasurements.columns)
    # show first 30 column names and last 10 to spot Potassium/time columns
    preview = []
    for i, c in enumerate(cols[:30]):
        preview.append({'pos': i, 'col': c})
    offset = max(0, len(cols) - 10)
    for i, c in enumerate(cols[offset:]):
        preview.append({'pos': offset + i, 'col': c})
    return pd.DataFrame(preview)
